    detail: Boolean(args?.detail),
    subkeys: Boolean(args?.subkeys),
    all: Boolean(args?.all),
    full: Boolean(args?.full),
    since: null,
  };


  if (a.detail && !a.name) return { ok: false, error: "detail requires name" };
